const TOPUP = {
  validPartitions: [],
  invalidPartitions: [],
  validBoundaries: [],
  invalidBoundaries: [],
  bonusAtThreshold: 0,   // the bonus credited for the smallest top-up that earns a bonus
};

// One test per COLLAPSED rule of the meal-price decision table.
const MEAL_TESTS = [
  { isStudent: false, isCombo: false, beforeEleven: false, expected: 35000 },
];

// Event sequences, each starting from a new ACTIVE card.
const CARD_SEQUENCES = [
  ['lock', 'unlock'],
];
const CARD_INVALID_COUNT = 0;
const CARD_NEGATIVE = { events: [], expectedState: '' };

const MEAL_UC_TESTS = [
  {
    id: 'UC-MAIN', description: 'Main scenario: an active card with enough balance pays for the meal',
    precondition: 'Kiosk is open; the card is placed on the reader',
    steps: ['Place the card on the reader', 'Choose a meal of 45,000 VND', 'Confirm the payment'],
    data: { cardState: 'ACTIVE', balance: '100000', price: '45000' },
    expected: 'Paid. New balance: 55,000 VND.',
  },
];

