// A. Top-up amount: 5 partitions (2 valid, 3 invalid), step 1,000.
const TOPUP = {
  validPartitions: [100000, 800000],                 // 20,000–499,000 (no bonus) · 500,000–2,000,000 (bonus)
  invalidPartitions: [10000, 2500000, 150500],       // too small · too large · not a multiple of 1,000
  validBoundaries: [20000, 499000, 500000, 2000000], // edges of both valid partitions
  invalidBoundaries: [19000, 2001000],
  bonusAtThreshold: 25000,                           // 5% of 500,000
};

// B. Collapsed decision table: single meals ignore the time ⇒ 2 + 4 = 6 rules.
const MEAL_TESTS = [
  { isStudent: true, isCombo: false, beforeEleven: false, expected: 31500 },  // R1 (time: don't care)
  { isStudent: false, isCombo: false, beforeEleven: true, expected: 35000 },  // R2 (time: don't care)
  { isStudent: true, isCombo: true, beforeEleven: true, expected: 40000 },    // R3 50,000 × 90% − 5,000
  { isStudent: true, isCombo: true, beforeEleven: false, expected: 45000 },   // R4
  { isStudent: false, isCombo: true, beforeEleven: true, expected: 45000 },   // R5
  { isStudent: false, isCombo: true, beforeEleven: false, expected: 50000 },  // R6
];

// C. Two transitions (T3, T4) enter the final state BLOCKED ⇒ two sequences.
const CARD_SEQUENCES = [
  ['lock', 'unlock', 'expire', 'renew', 'lock', 'expire', 'renew', 'reportLost'], // T1 T2 T5 T7 T1 T6 T7 T3
  ['lock', 'reportLost'],                                                        // T1 T4
];
const CARD_INVALID_COUNT = 13;   // 4 states × 5 events = 20 − 7 valid
const CARD_NEGATIVE = { events: ['reportLost', 'unlock'], expectedState: 'BLOCKED' };

// D. Use case “Buy a meal”: main scenario + 4 extensions + 2 boundary cases of the balance check.
const MEAL_UC_TESTS = [
  {
    id: 'UC-MAIN', description: 'Main scenario: an active card with enough balance pays for the meal',
    precondition: 'Kiosk is open; the card is placed on the reader',
    steps: ['Place the card on the reader', 'Choose a meal of 45,000 VND', 'Confirm the payment'],
    data: { cardState: 'ACTIVE', balance: '100000', price: '45000' },
    expected: 'Paid. New balance: 55,000 VND.',
  },
  {
    id: 'UC-E1', description: 'Extension: the card is locked',
    precondition: 'Kiosk is open; the card is placed on the reader',
    steps: ['Place the card on the reader', 'Choose a meal of 45,000 VND', 'Confirm the payment'],
    data: { cardState: 'LOCKED', balance: '100000', price: '45000' },
    expected: 'Card is locked. Unlock it at the counter.',
  },
  {
    id: 'UC-E2', description: 'Extension: the card is blocked (reported lost)',
    precondition: 'Kiosk is open; the card is placed on the reader',
    steps: ['Place the card on the reader', 'Choose a meal of 45,000 VND', 'Confirm the payment'],
    data: { cardState: 'BLOCKED', balance: '100000', price: '45000' },
    expected: 'Card is blocked. Please contact the canteen office.',
  },
  {
    id: 'UC-E3', description: 'Extension: the card has expired',
    precondition: 'Kiosk is open; the card is placed on the reader',
    steps: ['Place the card on the reader', 'Choose a meal of 45,000 VND', 'Confirm the payment'],
    data: { cardState: 'EXPIRED', balance: '100000', price: '45000' },
    expected: 'Card has expired. Renew it for the new term.',
  },
  {
    id: 'UC-E4', description: 'Extension: the balance is lower than the price',
    precondition: 'Kiosk is open; the card is placed on the reader',
    steps: ['Place the card on the reader', 'Choose a meal of 45,000 VND', 'Confirm the payment'],
    data: { cardState: 'ACTIVE', balance: '20000', price: '45000' },
    expected: 'Insufficient balance. Please top up 25,000 VND.',
  },
  {
    id: 'UC-B1', description: 'Boundary: the balance equals the price',
    precondition: 'Kiosk is open; the card is placed on the reader',
    steps: ['Place the card on the reader', 'Choose a meal of 45,000 VND', 'Confirm the payment'],
    data: { cardState: 'ACTIVE', balance: '45000', price: '45000' },
    expected: 'Paid. New balance: 0 VND.',
  },
  {
    id: 'UC-B2', description: 'Boundary: the balance is 1,000 VND short',
    precondition: 'Kiosk is open; the card is placed on the reader',
    steps: ['Place the card on the reader', 'Choose a meal of 45,000 VND', 'Confirm the payment'],
    data: { cardState: 'ACTIVE', balance: '44000', price: '45000' },
    expected: 'Insufficient balance. Please top up 1,000 VND.',
  },
];

